{
  "findings": [
    {
      "check_id": "CKV_AZURE_224",
      "title": "Ledger feature not enabled",
      "resource": "azurerm_mssql_database.main",
      "severity": "MEDIUM",
      "explanation": "The Ledger feature is not enabled, which is a risk for databases requiring cryptographic proof and nonrepudiation of data integrity. This could lead to tampering or integrity issues in sensitive data."
    },
    {
      "check_id": "CKV_AZURE_229",
      "title": "Database is not zone redundant",
      "resource": "azurerm_mssql_database.main",
      "severity": "MEDIUM",
      "explanation": "The database is not configured to be zone redundant, which could lead to availability issues in case of a zone failure."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"main\" {\n  name           = \"${var.project_name}-database\"\n  server_id      = azurerm_mssql_server.main.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 20\n  sku_name       = \"S0\"\n  tags           = var.common_tags\n\n  ledger_enabled = true\n  zone_redundant = true\n}",
  "fix_summary": "Enabled the Ledger feature for cryptographic proof and nonrepudiation of data integrity. Configured the database to be zone redundant to improve availability in case of a zone failure."
}
